args.command:
/bin/bash -lc "cat .gitignore; cat .next/cache/fetch-cache/8a2b4b418f91d2cf561e20b73503d9bfcd3a9444ad095c7dcaa382407d71a142; node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readdir, stat, readFile } from 'node:fs/promises'
const base = 'http://localhost:3000'
const cacheDir = '.next/cache/fetch-cache'
const entries = await readdir(cacheDir)
const cacheFile = "'`${cacheDir}/${entries[0]}`
const cached = JSON.parse(await readFile(cacheFile, '"'utf8'))
assert.deepEqual(cached.tags, ['products'])
const before = (await stat(cacheFile)).mtimeMs
for (let i = 0; i < 3; i++) {
  const response = await fetch(base)
  assert.equal(response.status, 200)
  const html = await response.text()
  assert.match(html, /Product catalog/)
  assert.match(html, /Laptop/)
  assert.match(html, /\\"'$999'"\\.00/)
  assert.match(html, /Sync latest catalog/)
}
assert.equal((await stat(cacheFile)).mtimeMs, before, 'Browsing should reuse cached products')
const html = await (await fetch(base)).text()
const action = html.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)
assert.ok(action, '"'The native form should have a Server Action')
const form = new FormData()
form.set(action[1], '')
const start = performance.now()
const synced = await fetch(base, { method: 'POST', body: form, headers: { Origin: base } })
assert.equal(synced.status, 200)
assert.match(await synced.text(), /Laptop/)
console.log("'`Native form submitted successfully in ${Math.round(performance.now() - start)} ms`)
let refreshed = false
for (let i = 0; i < 30; i++) {
  await (await fetch(base)).text()
  if ((await stat(cacheFile)).mtimeMs > before) {
    refreshed = true
    break
  }
  await new Promise(resolve => setTimeout(resolve, 100))
}
assert.ok(refreshed, '"'Sync should cause the shared product cache to refresh')
console.log('PASS: catalog renders, repeated reads reuse products, native form invokes the action, and the product cache refreshes after sync')
NODE"

